// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        // Restrict inputs: _tos length must be exactly 0 to test the require
        vm.assume(_tos.length == 0);
        // Call transfer and capture revert status
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v, _decimals));
        // Reference C should revert because of require(_tos.length > 0)
        assertTrue(!success, "Reference should revert on empty _tos array");
    }
}

